// ProfileTab.js
import React, { useState, useEffect } from 'react';
import {
  Box, Typography, TextField, Button, IconButton, InputAdornment, Paper,
  Dialog, DialogTitle, DialogContent, DialogActions, Grid, Snackbar, Alert,
  CircularProgress, FormControl
} from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { useAuth } from './AuthContext';

const ProfileTab = () => {
  const { user } = useAuth();
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [lastUpdated, setLastUpdated] = useState({ username: null, password: null });
  const [passwordError, setPasswordError] = useState('');
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [openConfirmUsername, setOpenConfirmUsername] = useState(false);
  const [openConfirmPassword, setOpenConfirmPassword] = useState(false);

  useEffect(() => {
    const storedData = localStorage.getItem(`lastUpdated_${user?.workerID}`);
    if (storedData) setLastUpdated(JSON.parse(storedData));
  }, [user?.workerID]);

  const canUpdateToday = (field) => {
    if (!lastUpdated[field]) return true;
    const last = new Date(lastUpdated[field]);
    const today = new Date();
    last.setHours(0, 0, 0, 0);
    today.setHours(0, 0, 0, 0);
    return last.getTime() !== today.getTime();
  };

  const togglePasswordVisibility = () => setShowPassword(prev => !prev);
  const showSnackbarMessage = (message, severity = 'success') =>
    setSnackbar({ open: true, message, severity });

  const verifyPassword = async () => {
    if (!passwordConfirm) {
      setPasswordError('Please enter your password');
      return false;
    }

    try {
      const response = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: user.username, password: passwordConfirm }),
      });

      if (response.ok) return true;
      const data = await response.json();
      setPasswordError(data.message || 'Incorrect password');
      return false;
    } catch (err) {
      setPasswordError('Error verifying password');
      return false;
    }
  };

  const confirmUsernameUpdate = async () => {
    if (!user) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    if (!await verifyPassword()) return;
    setIsUpdating(true);

    try {
      const response = await fetch('http://localhost:8080/worker/update', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workerID: user.workerID,
          username: newUsername
        }),
      });

      const data = await response.json();

      if (response.ok) {
        const updatedUser = { ...user, username: newUsername };
        localStorage.setItem('user', JSON.stringify(updatedUser));
        localStorage.setItem('username', newUsername);

        const updatedTimestamps = {
          ...lastUpdated,
          username: new Date().toISOString()
        };
        localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
        setLastUpdated(updatedTimestamps);
        setNewUsername('');
        showSnackbarMessage('Username updated successfully!');
      } else {
        showSnackbarMessage(data.message || 'Failed to update username', 'error');
      }
    } catch (err) {
      showSnackbarMessage('Error updating username: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmUsername(false);
    }
  };

  const confirmPasswordUpdate = async () => {
    if (!user) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    if (!await verifyPassword()) return;
    setIsUpdating(true);

    try {
      const response = await fetch('http://localhost:8080/worker/update', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workerID: user.workerID,
          password: newPassword
        }),
      });

      const data = await response.json();

      if (response.ok) {
        const updatedTimestamps = {
          ...lastUpdated,
          password: new Date().toISOString()
        };
        localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
        setLastUpdated(updatedTimestamps);
        setNewPassword('');
        setConfirmPassword('');
        showSnackbarMessage('Password updated successfully!');
      } else {
        showSnackbarMessage(data.message || 'Failed to update password', 'error');
      }
    } catch (err) {
      showSnackbarMessage('Error updating password: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmPassword(false);
    }
  };

  const handleCloseSnackbar = () => setSnackbar(prev => ({ ...prev, open: false }));

  if (!user) {
    return <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '70vh' }}><CircularProgress /></Box>;
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', textAlign: 'center', mb: 4 }}>
        User Profile
      </Typography>

      <Paper elevation={3} sx={{ p: 4, maxWidth: 600, mx: 'auto' }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Typography variant="h5" align="center">{user.firstName} {user.lastName}</Typography>
            <Typography variant="subtitle1" align="center" sx={{ color: 'text.secondary', mb: 2 }}>
              {user.admin ? 'Administrator' : 'Inspector'}
            </Typography>
          </Grid>

          {/* Username */}
          <Grid item xs={12}>
            <Typography variant="h6">Username</Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              Current: <strong>{user.username}</strong>
            </Typography>
            <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start' }}>
              <TextField
                fullWidth label="New Username" value={newUsername} onChange={e => setNewUsername(e.target.value)}
                helperText="You can only change your username once per day"
              />
              <Button variant="contained" onClick={() => {
                if (!newUsername) return showSnackbarMessage('Please enter a new username', 'error');
                if (!canUpdateToday('username')) return showSnackbarMessage('You can only change your username once per day', 'warning');
                setPasswordConfirm('');
                setPasswordError('');
                setOpenConfirmUsername(true);
              }} disabled={isUpdating}>
                Change
              </Button>
            </Box>
          </Grid>

          {/* Password */}
          <Grid item xs={12}>
            <Typography variant="h6" sx={{ mt: 2 }}>Password</Typography>
            <TextField
              fullWidth label="New Password" type={showPassword ? 'text' : 'password'} value={newPassword}
              onChange={e => setNewPassword(e.target.value)} margin="normal"
              helperText="Must be at least 8 characters with 1 special character"
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={togglePasswordVisibility}>
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            <TextField
              fullWidth label="Confirm New Password" type={showPassword ? 'text' : 'password'} value={confirmPassword}
              onChange={e => setConfirmPassword(e.target.value)} margin="normal"
              error={newPassword !== confirmPassword && confirmPassword !== ''}
              helperText={newPassword !== confirmPassword && confirmPassword !== ''
                ? 'Passwords do not match'
                : 'You can only change your password once per day'}
            />
            <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
              <Button variant="contained" onClick={() => {
                if (!newPassword) return showSnackbarMessage('Please enter a new password', 'error');
                if (newPassword !== confirmPassword) return showSnackbarMessage('Passwords do not match', 'error');
                if (!canUpdateToday('password')) return showSnackbarMessage('You can only change your password once per day', 'warning');
                setPasswordConfirm('');
                setPasswordError('');
                setOpenConfirmPassword(true);
              }} disabled={isUpdating}>
                Update Password
              </Button>
            </Box>
          </Grid>
        </Grid>
      </Paper>

      {/* Username Confirm Dialog */}
      <Dialog open={openConfirmUsername} onClose={() => setOpenConfirmUsername(false)}>
        <DialogTitle>Confirm Username Change</DialogTitle>
        <DialogContent>
          <Typography>Change username to <strong>{newUsername}</strong>?</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2, mb: 2 }}>
            You will use this new username next time you log in.
          </Typography>
          <FormControl fullWidth margin="normal">
            <TextField
              label="Enter Your Password to Confirm"
              type="password"
              value={passwordConfirm}
              onChange={e => { setPasswordConfirm(e.target.value); setPasswordError(''); }}
              error={!!passwordError}
              helperText={passwordError || 'Enter your password to confirm this action'}
            />
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenConfirmUsername(false)} disabled={isUpdating}>Cancel</Button>
          <Button onClick={confirmUsernameUpdate} variant="contained" disabled={!passwordConfirm || isUpdating}>
            {isUpdating ? <CircularProgress size={24} /> : 'Confirm'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Password Confirm Dialog */}
      <Dialog open={openConfirmPassword} onClose={() => setOpenConfirmPassword(false)}>
        <DialogTitle>Confirm Password Change</DialogTitle>
        <DialogContent>
          <Typography>Are you sure you want to change your password?</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2, mb: 2 }}>
            You will use this new password the next time you log in.
          </Typography>
          <FormControl fullWidth margin="normal">
            <TextField
              label="Enter Your Password to Confirm"
              type="password"
              value={passwordConfirm}
              onChange={e => { setPasswordConfirm(e.target.value); setPasswordError(''); }}
              error={!!passwordError}
              helperText={passwordError || 'Enter your current password to confirm this action'}
            />
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenConfirmPassword(false)} disabled={isUpdating}>Cancel</Button>
          <Button onClick={confirmPasswordUpdate} variant="contained" disabled={!passwordConfirm || isUpdating}>
            {isUpdating ? <CircularProgress size={24} /> : 'Confirm'}
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={snackbar.open} autoHideDuration={6000} onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ProfileTab;
